export interface OrderMessage { id: string; customer_id: string; total_minor: number }

export const toMessage = (o: Order): OrderMessage => ({
  id: o.id, customer_id: o.customer.id, total_minor: o.total.minorUnits,
});

export const fromMessage = (m: OrderMessage): Order =>
  Order.rehydrate(m.id, m.customer_id, Money.minor(m.total_minor));
