export const OrderFromMessage = z.object({
  id: z.string().min(1),
  customer_id: z.string().min(1),
  total_minor: z.number().int().nonnegative(),
}).transform((m) => Order.rehydrate(m.id, m.customer_id, Money.minor(m.total_minor)));

